const app=$('#app'),modal=$('#modal'),body=$('#modal-body'),toastEl=$('#toast'),printArea=$('#print-area');
// The CSP (style-src 'self') ignores style="" attributes in markup; re-apply them through CSSOM, which CSP allows.
const cssom=n=>{if(n.nodeType!==1)return;if(n.hasAttribute('style'))n.style.cssText=n.getAttribute('style');n.querySelectorAll('[style]').forEach(e=>{e.style.cssText=e.getAttribute('style')})};
new MutationObserver(ms=>{for(const m of ms)m.addedNodes.forEach(cssom)}).observe(document.documentElement,{childList:true,subtree:true});
const store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v)}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
// fr/en are written inline; ar/es/de/zh come from staff-i18n.js, keyed by the English text.
const LANGS={fr:['Français','fr-MA'],en:['English','en-GB'],ar:['العربية','ar-MA'],es:['Español','es-ES'],de:['Deutsch','de-DE'],zh:['中文','zh-CN']},T=window.APS_I18N||{};
let lang=LANGS[store.get('aps-order-staff-lang','fr')]?store.get('aps-order-staff-lang','fr'):'fr',csrf='',me=null,state=null,view='orders',activation='',enroll=null,recovery=null;
let adminRid=null,take=store.get('aps-order-take',null),saver=store.get('aps-order-saver',{on:true,min:2}),saverTimer=null,upload=null;
let menuCat='all',menuQuery='',sound=!!store.get('aps-order-sound',false),offset=0,pollTimer=null,seenOrders=null,seenCalls=null,fresh=new Set(),detail=null,actx=null,wakeLock=null;
const FINAL=['served','cancelled'],FLOW=['new','confirmed','preparing','ready'],NEXT={new:'confirmed',confirmed:'preparing',preparing:'ready',ready:'served'};
const ALLERGENS={gluten:['Gluten','Gluten'],crustaceans:['Crustacés','Crustaceans'],eggs:['Œufs','Eggs'],fish:['Poisson','Fish'],peanuts:['Arachides','Peanuts'],soy:['Soja','Soy'],milk:['Lait','Milk'],nuts:['Fruits à coque','Nuts'],celery:['Céleri','Celery'],mustard:['Moutarde','Mustard'],sesame:['Sésame','Sesame'],sulphites:['Sulfites','Sulphites'],lupin:['Lupin','Lupin'],molluscs:['Mollusques','Molluscs']};

const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(fr,en)=>lang==='fr'?fr:lang==='en'?en:(T[lang]?.[en]||en);
const labels={new:['Nouvelle','New'],confirmed:['Confirmée','Confirmed'],preparing:['En cuisine','In the kitchen'],ready:['Prête','Ready'],served:['Servie','Served'],cancelled:['Annulée','Cancelled'],pending:['À encaisser','Unpaid'],paid:['Encaissée','Paid'],failed:['Échec','Failed'],refunded:['Remboursée','Refunded'],active:['Actif','Active'],trial:['Essai','Trial'],past_due:['Impayé','Past due'],suspended:['Suspendu','Suspended'],restaurant_admin:['Responsable','Manager'],staff:['Équipe','Staff'],platform_admin:['Administrateur APS','APS administrator'],table:['À table','At table'],counter:['Comptoir','Counter'],takeaway:['À emporter','Takeaway'],waiter:['Appelle un serveur','Calls a waiter'],bill:['Demande l’addition','Asks for the bill'],image:['Image','Image'],video:['Vidéo','Video']};
const label=x=>labels[x]?t(...labels[x]):x;
const locale=()=>LANGS[lang][1];
const langSelect=()=>`<label class="lang-select">${I.globe}<select data-lang-select aria-label="Langue / Language">${Object.entries(LANGS).map(([k,v])=>`<option value="${k}" ${k===lang?'selected':''}>${v[0]}</option>`).join('')}</select></label>`;
const iname=i=>i?.['name_'+lang]||i?.name_fr||'';
function setDir(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr'}
const money=(n,c='MAD')=>new Intl.NumberFormat(locale(),{style:'currency',currency:c}).format((+n||0)/100);
const date=x=>x?new Date(typeof x==='number'?x*1000:x+'T12:00:00').toLocaleString(locale(),{dateStyle:'medium',timeStyle:typeof x==='number'?'short':undefined}):'—';
const clock=x=>new Date(x*1000).toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'});
const now=()=>Math.floor(Date.now()/1000+offset);
const mins=ts=>Math.max(0,Math.floor((now()-ts)/60));
const ago=ts=>{const m=mins(ts);return m<1?t('à l’instant','just now'):m<60?m+' min':Math.floor(m/60)+' h '+String(m%60).padStart(2,'0')};
const allergensOf=v=>{try{const a=JSON.parse(v||'[]');return Array.isArray(a)?a.filter(x=>ALLERGENS[x]):[]}catch{return[]}};
const aName=a=>t(...ALLERGENS[a]);
const restaurantOf=id=>state?.restaurants.find(r=>r.id==id);
const currencyOf=rid=>restaurantOf(rid)?.currency||'MAD';
const currentRestaurant=()=>me?.role==='platform_admin'?null:state?.restaurants[0];
// Restaurant the reception, waiter, screens and settings pages act on (platform admins pick one).
const workRid=()=>me?.role==='platform_admin'?(restaurantOf(adminRid)?adminRid:state?.restaurants[0]?.id):me?.restaurant_id;
const adminPicker=()=>me?.role==='platform_admin'&&state.restaurants.length?`<label class="lang-select">${I.store}<select data-admin-rid aria-label="Restaurant">${state.restaurants.map(r=>`<option value="${r.id}" ${r.id==workRid()?'selected':''}>${h(r.name)}</option>`).join('')}</select></label>`:'';
const isManager=()=>me&&me.role!=='staff';

