/* ---------- Analytics ---------- */
function analyticsPage(){
 const r=currentRestaurant(),cur=r?.currency||'MAD',since=now()-30*86400;
 const recent=state.orders.filter(o=>o.created_at>=since),valid=recent.filter(o=>o.status!=='cancelled'),paid=valid.filter(o=>o.payment_status==='paid');
 const sales=valid.reduce((s,o)=>s+o.total,0),cancelled=recent.length-valid.length;
 const days=[];for(let i=13;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);days.push({d,v:0,n:0})}
 for(const o of valid){const od=new Date(o.created_at*1000);od.setHours(0,0,0,0);const day=days.find(x=>x.d.getTime()===od.getTime());if(day){day.v+=o.total;day.n++}}
 const max=Math.max(1,...days.map(x=>x.v));
 const hours=Array(24).fill(0);valid.forEach(o=>hours[new Date(o.created_at*1000).getHours()]++);const used=hours.map((v,i)=>v?i:-1).filter(i=>i>=0);const h0=used.length?Math.min(...used):11,h1=used.length?Math.max(...used):23;const hmax=Math.max(1,...hours);
 const top=state.top_items||[],tmax=Math.max(1,...top.map(x=>+x.quantity)),fb=(state.feedback||[]).filter(f=>!r||f.restaurant_id==r.id);
 return heading(t('Analyses','Analytics'),t('30 derniers jours, calculés à partir des commandes enregistrées (hors annulations).','Last 30 days, from recorded orders (cancellations excluded).'))
 +`<div class="kpis"><div class="kpi"><span>${t('Commandes','Orders')}</span><strong>${valid.length}</strong><small>${(valid.length/30).toFixed(1)} ${t('par jour','per day')}</small></div><div class="kpi"><span>${t('Ventes','Sales')}</span><strong>${money(sales,cur)}</strong><small>${money(paid.reduce((s,o)=>s+o.total,0),cur)} ${t('encaissés','collected')}</small></div><div class="kpi"><span>${t('Panier moyen','Average order')}</span><strong>${money(valid.length?Math.round(sales/valid.length):0,cur)}</strong><small>${valid.length?(valid.reduce((s,o)=>s+o.guest_count,0)/valid.length).toFixed(1):0} ${t('pers. par commande','guests per order')}</small></div><div class="kpi"><span>${t('Annulations','Cancellations')}</span><strong>${cancelled}</strong><small>${recent.length?Math.round(cancelled/recent.length*100):0} %</small></div><div class="kpi"><span>${t('Note des clients','Guest rating')}</span><strong>${fb.length?(fb.reduce((s,f)=>s+ +f.rating,0)/fb.length).toFixed(1).replace('.',locale().startsWith('fr')||locale().startsWith('es')||locale().startsWith('de')?',':'.')+' ★':'—'}</strong><small>${fb.length} ${t('avis','reviews')}</small></div></div>`
 +`<div class="charts"><section class="panel"><div class="panel-head"><h2>${t('Ventes par jour','Sales per day')}</h2><span class="badge">${t('max','max')} ${money(max===1?0:max,cur)}</span></div><div class="panel-body"><div class="bars">${days.map((x,i)=>`<div class="bar ${i===13?'today':''}" style="height:${(x.v/max*100).toFixed(1)}%" data-v="${h(x.d.toLocaleDateString(locale(),{day:'numeric',month:'short'}))} · ${h(money(x.v,cur))} · ${x.n}"></div>`).join('')}</div><div class="bar-labels">${days.map(x=>`<span>${x.d.getDate()}</span>`).join('')}</div></div></section>
 <section class="panel"><div class="panel-head"><h2>${t('Plats les plus commandés','Best sellers')}</h2></div><div class="panel-body">${top.length?`<div class="hbars">${top.map(x=>`<div class="hbar"><span>${h(x.item_name)}</span><span>${x.quantity} · ${money(x.revenue,cur)}</span><div><i style="width:${(x.quantity/tmax*100).toFixed(1)}%"></i></div></div>`).join('')}</div>`:`<p class="empty">${t('Aucune vente sur la période.','No sales in this period.')}</p>`}</div></section></div>`
 +`<section class="panel"><div class="panel-head"><h2>${t('Affluence par heure','Orders by hour')}</h2></div><div class="panel-body"><div class="bars" style="height:140px;background-size:auto">${hours.slice(h0,h1+1).map((v,i)=>`<div class="bar" style="height:${(v/hmax*100).toFixed(1)}%" data-v="${h0+i}h · ${v}"></div>`).join('')}</div><div class="bar-labels">${hours.slice(h0,h1+1).map((_,i)=>`<span>${h0+i}h</span>`).join('')}</div></div></section>`
 +`<section class="panel"><div class="panel-head"><h2>${t('Avis des clients','Guest feedback')}</h2><span class="badge">${fb.length}</span></div>${fb.length?`<div class="feedback">${fb.map(f=>`<div class="fb"><span class="fb-stars" aria-label="${f.rating}/5">${[1,2,3,4,5].map(n=>`<i class="${n<=f.rating?'on':''}">${I.star}</i>`).join('')}</span><div>${f.rating_comment?`<p>“${h(f.rating_comment)}”</p>`:`<p class="muted">${t('Sans commentaire','No comment')}</p>`}<small>${f.table_label?t('Table ','Table ')+h(f.table_label)+' · ':''}#${h(f.public_id)} · ${date(f.rated_at)}</small></div></div>`).join('')}</div>`:`<p class="empty">${t('Les notes apparaissent quand une commande servie et encaissée est évaluée par le client.','Ratings appear when guests rate a served and paid order.')}</p>`}</section>`;
}

/* ---------- Team, restaurants, audit, security ---------- */
/* ---------- Order taking: reception desk and waiter phone ---------- */
function freshTake(type){return{rid:workRid(),type:type||'counter',table:null,picked:false,lines:[],cat:'all',q:'',guests:1,name:'',note:'',allergies:[],pay:'table',paid:false}}
function ensureTake(){if(!take||take.rid!=workRid()||!Array.isArray(take.lines))take=freshTake(view==='waiter'?'table':'counter');take.lines=take.lines.filter(l=>state.items.some(i=>i.id==l.item_id&&+i.available));if(take.table&&!state.tables.some(x=>x.id==take.table&&+x.active))take.table=null}
const saveTake=()=>store.set('aps-order-take',take);
const takeQty=id=>take.lines.filter(l=>l.item_id==id).reduce((n,l)=>n+l.quantity,0);
const takeCount=()=>take.lines.reduce((n,l)=>n+l.quantity,0);
function takeTotals(){const r=restaurantOf(take.rid)||{},sub=take.lines.reduce((s,l)=>s+(+(state.items.find(i=>i.id==l.item_id)?.price||0))*l.quantity,0),tax=Math.floor((sub*(+r.tax_rate||0)+5000)/10000),service=Math.floor((sub*(+r.service_rate||0)+5000)/10000);return{sub,tax,service,total:sub+tax+service}}
function takeWhere(){if(take.type==='table'){const tb=state.tables.find(x=>x.id==take.table);return tb?t('Table ','Table ')+tb.label:t('Choisir une table','Pick a table')}return label(take.type)}
function takeItems(){const q=take.q.toLocaleLowerCase();return state.items.filter(i=>i.restaurant_id==take.rid&&(take.cat==='all'||i.category_id==take.cat)&&state.categories.some(c=>c.id==i.category_id&&+c.active)&&(!q||(i.name_fr+' '+i.name_en+' '+i.name_ar+' '+iname(i)).toLocaleLowerCase().includes(q)))}
function takeGrid(){const cur=currencyOf(take.rid),items=takeItems();return items.length?items.map(i=>{const q=takeQty(i.id),off=!+i.available;return`<div class="tile ${q?'in':''} ${off?'off':''}"><button class="tile-main" data-take-add="${i.id}" ${off?'disabled':''}>${i.image_path?`<img src="${h(i.image_path)}" alt="" loading="lazy">`:`<span class="tile-mono" aria-hidden="true">${h((iname(i)||'·').trim()[0].toUpperCase())}</span>`}<span class="tile-name">${h(iname(i))}</span><span class="tile-price num">${off?t('Épuisé','Sold out'):money(i.price,cur)}</span></button>${q?`<span class="tile-q num">${q}</span><button class="tile-dec" data-take-dec="${i.id}" aria-label="${t('Retirer','Remove')} ${h(iname(i))}">${I.minus}</button>`:''}</div>`}).join(''):`<p class="empty">${t('Aucun plat ne correspond.','No matching dish.')}</p>`}
function takeMenu(){const cats=state.categories.filter(c=>c.restaurant_id==take.rid&&+c.active);return`<div class="take-tools"><div class="chips scroll" role="group" aria-label="${t('Catégories','Categories')}">${[['all',t('Tout','All')],...cats.map(c=>[c.id,iname(c)])].map(([id,n])=>`<button data-take-cat="${id}" aria-pressed="${String(take.cat)===String(id)}">${h(n)}</button>`).join('')}</div><label class="search">${I.search}<input id="take-search" type="search" value="${h(take.q)}" placeholder="${t('Rechercher un plat','Search a dish')}" autocomplete="off"></label></div><div class="take-grid" id="take-grid">${takeGrid()}</div>`}
function takeTicketBody(){
 const cur=currencyOf(take.rid),x=takeTotals(),r=restaurantOf(take.rid)||{},tables=state.tables.filter(q=>q.restaurant_id==take.rid&&+q.active);
 return`<div class="field"><span class="label">${t('Pour','For')}</span><div class="seg">${['table','counter','takeaway'].map(k=>`<button type="button" data-take-type="${k}" aria-pressed="${take.type===k}">${h(label(k))}</button>`).join('')}</div>${take.type==='table'?`<select class="table-pick" data-take-table aria-label="${t('Table','Table')}"><option value="">${t('Choisir une table…','Pick a table…')}</option>${tables.map(q=>`<option value="${q.id}" ${q.id==take.table?'selected':''}>${t('Table ','Table ')}${h(q.label)}${q.zone?' · '+h(q.zone):''}</option>`).join('')}</select>`:''}</div>
 <div class="take-lines">${take.lines.length?take.lines.map((l,n)=>{const i=state.items.find(q=>q.id==l.item_id);return i?`<div class="tl"><div class="qty"><button type="button" data-take-line="${n}" data-d="-1" aria-label="−">${I.minus}</button><b class="num">${l.quantity}</b><button type="button" data-take-line="${n}" data-d="1" aria-label="+">${I.plus}</button></div><div class="tl-name"><strong>${h(iname(i))}</strong><input data-take-note="${n}" value="${h(l.note)}" maxlength="300" placeholder="${t('Préférence (sans oignon…)','Preference (no onion…)')}" aria-label="${t('Préférence','Preference')}"></div><span class="num">${money(i.price*l.quantity,cur)}</span></div>`:''}).join(''):`<p class="empty small">${t('Touchez un plat pour l’ajouter.','Tap a dish to add it.')}</p>`}</div>
 <div class="form-grid"><div class="field"><label for="take-guests">${t('Personnes','Guests')}</label><input id="take-guests" data-take-field="guests" type="number" min="1" max="30" value="${take.guests}" inputmode="numeric"></div><div class="field"><label for="take-name">${t('Nom du client','Customer name')}</label><input id="take-name" data-take-field="name" maxlength="100" value="${h(take.name)}" autocomplete="off"></div><div class="field full"><label for="take-note">${t('Note pour la cuisine','Note for the kitchen')}</label><input id="take-note" data-take-field="note" maxlength="1000" value="${h(take.note)}" autocomplete="off"></div></div>
 <details class="more-langs" ${take.allergies.length?'open':''}><summary>⚠ ${t('Allergies','Allergies')}${take.allergies.length?' · '+take.allergies.length:''}</summary><div class="allergen-picks">${Object.keys(ALLERGENS).map(a=>`<label><input type="checkbox" data-take-allergy="${a}" ${take.allergies.includes(a)?'checked':''}> ${h(aName(a))}</label>`).join('')}</div></details>
 ${take.type==='table'?`<div class="field"><span class="label">${t('Paiement','Payment')}</span><div class="seg">${['table','counter'].map(k=>`<button type="button" data-take-pay="${k}" aria-pressed="${take.pay===k}">${h(label(k))}</button>`).join('')}</div></div>`:''}
 <label class="checkline"><input type="checkbox" data-take-paid ${take.paid?'checked':''}> ${t('Déjà encaissée','Already paid')}</label>
 <div class="totals"><div><span>${t('Sous-total','Subtotal')}</span><span>${money(x.sub,cur)}</span></div>${x.tax?`<div><span>${t('Taxe','Tax')} ${(+r.tax_rate||0)/100}%</span><span>${money(x.tax,cur)}</span></div>`:''}${x.service?`<div><span>Service</span><span>${money(x.service,cur)}</span></div>`:''}<div class="grand"><span>${t('Total','Total')}</span><span>${money(x.total,cur)}</span></div></div>
 <button class="button block big" data-action="take-send" ${take.lines.length&&(take.type!=='table'||take.table)?'':'disabled'}>${I.check} ${t('Envoyer en cuisine','Send to kitchen')} · ${money(x.total,cur)}</button>
 ${take.lines.length?`<button class="text-button" data-action="take-clear">${t('Vider la commande','Clear order')}</button>`:''}`;
}
function takeBar(){const n=takeCount();return n?`<button class="take-bar" data-action="take-review"><span>${I.bag} ${n} · ${h(takeWhere())}</span><span class="num">${money(takeTotals().total,currencyOf(take.rid))} →</span></button>`:''}
function paintTake(){const g=$('#take-grid');if(g)g.innerHTML=takeGrid();const tk=$('#take-ticket');if(tk)tk.innerHTML=takeTicketBody();const b=$('#take-bar');if(b)b.innerHTML=takeBar();const w=$('#take-where');if(w)w.textContent=takeWhere();saveTake()}
function receptionPage(){
 ensureTake();if(!take.picked){take.picked=true}
 return heading(t('Réception','Reception'),t('Commandes au comptoir, à emporter ou pour une table, envoyées directement en cuisine.','Counter, takeaway or table orders, sent straight to the kitchen.'),`${adminPicker()}<button class="button secondary ${saver.on?'on-soft':''}" data-action="saver-settings" title="${t('Veille de l’écran','Screen saver')}">${I.moon} ${saver.on?t('Veille','Saver')+' · '+saver.min+' min':t('Veille coupée','Saver off')}</button><button class="button secondary" data-action="kiosk">${I.full} ${t('Plein écran','Full screen')}</button>`)
 +`<div class="take-split"><section class="take-menu">${takeMenu()}</section><aside class="panel take-panel"><div class="panel-head"><h2 id="take-where">${h(takeWhere())}</h2><span class="badge">${t('Réception','Reception')}</span></div><div class="panel-body take-ticket" id="take-ticket">${takeTicketBody()}</div></aside></div><div class="take-dock" id="take-bar">${takeBar()}</div>`;
}
function tableState(tb){const os=state.orders.filter(o=>o.table_id==tb.id&&!FINAL.includes(o.status)),unpaid=state.orders.filter(o=>o.table_id==tb.id&&o.status==='served'&&o.payment_status==='pending'),calls=state.calls.filter(c=>c.table_id==tb.id);return{os,unpaid,calls,cls:calls.length?'call':os.some(o=>o.status==='ready')?'ready':os.length?'busy':unpaid.length?'unpaid':'free'}}
function waiterPage(){
 ensureTake();
 if(!take.picked){
  const tables=state.tables.filter(q=>q.restaurant_id==take.rid&&+q.active),cur=currencyOf(take.rid);
  return heading(t('Prise de commande','Take an order'),t('Choisissez une table ou un client sans table.','Pick a table or a walk-in guest.'),adminPicker())
  +`<div class="walkin"><button class="button secondary big" data-take-start="counter">${I.desk} ${t('Comptoir','Counter')}</button><button class="button secondary big" data-take-start="takeaway">${I.bag} ${t('À emporter','Takeaway')}</button></div>`
  +(tables.length?`<div class="table-grid">${tables.map(tb=>{const s=tableState(tb);return`<button class="tcard ${s.cls}" data-take-start="table" data-id="${tb.id}"><span class="tlabel">${h(tb.label)}</span><span class="tzone">${h(tb.zone||'')}${tb.zone?' · ':''}${tb.seats} ${t('pl.','seats')}</span><span class="tstate">${s.calls.length?`${I.bell} ${h(label(s.calls[0].kind))}`:s.os.length?`${s.os.length} ${t('en cours','open')} · ${h(label(s.os.sort((a,b)=>FLOW.indexOf(b.status)-FLOW.indexOf(a.status))[0].status))}`:s.unpaid.length?`${t('À encaisser','To collect')} ${money(s.unpaid.reduce((n,o)=>n+o.total,0),cur)}`:t('Libre','Free')}</span></button>`}).join('')}</div>`:`<div class="panel"><p class="empty"><strong>${t('Aucune table','No tables yet')}</strong>${t('Ajoutez des tables dans « Tables & QR ».','Add tables in “Tables & QR”.')}</p></div>`);
 }
 return`<div class="take-head"><button class="icon-btn" data-action="take-back" aria-label="${t('Changer de table','Change table')}">${I.x}</button><div><strong id="take-where">${h(takeWhere())}</strong><small>${t('Touchez un plat pour l’ajouter','Tap a dish to add it')}</small></div></div><section class="take-menu">${takeMenu()}</section><div class="take-dock always" id="take-bar">${takeBar()}</div>`;
}
async function takeSend(btn){
 const r=restaurantOf(take.rid);if(btn)btn.disabled=true;
 try{
  const d={order_type:take.type,guest_count:Math.max(1,Math.min(30,+take.guests||1)),customer_name:take.name.trim(),customer_note:take.note.trim(),allergies:take.allergies,payment_method:take.pay,paid:take.paid,items:take.lines.map(l=>({item_id:l.item_id,quantity:l.quantity,note:(l.note||'').trim()}))};
  if(take.type==='table')d.table_id=+take.table;if(me.role==='platform_admin')d.restaurant_id=+take.rid;
  const x=await api('staff-order-create',d),where=takeWhere(),wasWaiter=view==='waiter';
  take=freshTake(wasWaiter?'table':take.type);saveTake();if(navigator.vibrate)navigator.vibrate(60);
  if(modal.open)modal.close();await load(true);render();
  if(wasWaiter){toast(t('Commande envoyée en cuisine · ','Order sent to the kitchen · ')+where);return}
  const url=location.origin+'/r/'+(x.slug||r?.slug||'')+'/#o='+x.public_id+'.'+x.status_token;
  dialog(`${t('Commande','Order')} #${h(x.public_id)}`,`<div class="sent"><span class="sent-check">${I.check}</span><h3>${t('Envoyée en cuisine','Sent to the kitchen')}</h3><p>${h(where)} · ${money(x.total,x.currency)}</p></div><div class="qr">${qrSvg(url)}</div><p class="center muted">${t('Le client scanne ce code pour suivre sa commande puis la noter.','The guest scans this code to follow the order, then rate it.')}</p><div class="row-actions"><button class="button" data-action="print-order" data-id="${x.id}">${I.print} ${t('Ticket cuisine','Kitchen ticket')}</button><button class="button secondary" data-action="close-modal">${I.plus} ${t('Nouvelle commande','New order')}</button></div>`);
 }catch(e){toast(message(e.message),true);if(btn)btn.disabled=false}
}

/* ---------- Energy saver: after idle on the reception screen, only the logo stays, a touch wakes it ---------- */
function saverArm(){clearTimeout(saverTimer);if(!me||view!=='reception'||!saver.on||$('#saver'))return;saverTimer=setTimeout(saverShow,saver.min*60000)}
function saverShow(){
 if(!me||view!=='reception'||$('#saver'))return;const r=restaurantOf(workRid());
 const el=document.createElement('div');el.id='saver';el.setAttribute('role','button');el.setAttribute('aria-label',t('Touchez pour réactiver','Touch to wake'));el.tabIndex=0;
 el.innerHTML=`<div class="saver-logo">${r?.logo_path?`<img src="${h(r.logo_path)}" alt="">`:`<span class="mark">${h(r?.name||'APS ORDER')}</span>`}<small>${t('Touchez l’écran','Touch the screen')}</small></div>`;
 el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();saverHide()});document.body.appendChild(el);
 // Let the device's own screen timeout apply while the saver is up.
 try{wakeLock?.release()}catch{}wakeLock=null;
}
function saverHide(){$('#saver')?.remove();requestWake();saverArm()}
['pointerdown','keydown','wheel','touchstart'].forEach(ev=>document.addEventListener(ev,e=>{if($('#saver')){if(ev==='keydown')saverHide();return}saverArm()},{capture:true,passive:true}));

/* ---------- Screens (digital signage) ---------- */
const online=s=>s.last_seen&&now()-s.last_seen<150;
function screensPage(){
 const rid=workRid(),screens=(state.screens||[]).filter(s=>s.restaurant_id==rid),media=(state.signage||[]).filter(c=>c.restaurant_id==rid),targets=state.signage_targets||[];
 const used=media.reduce((n,c)=>n+ +c.bytes,0),player=location.origin+'/screen';
 const tg=c=>{const ids=targets.filter(x=>x.content_id==c.id).map(x=>x.screen_id);return ids.includes(null)||!ids.length?t('Tous les écrans','All screens'):ids.map(id=>screens.find(s=>s.id==id)?.name||'?').join(', ')};
 const sched=c=>c.start_date||c.end_date?`${c.start_date?date(c.start_date):'…'} → ${c.end_date?date(c.end_date):'…'}`:t('Toujours','Always');
 return heading(t('Écrans','Screens'),t('Affichage dynamique : images et vidéos en boucle sur vos téléviseurs.','Digital signage: images and videos looping on your TVs.'),`${adminPicker()}<button class="button secondary" data-action="screen-new">${I.plus} ${t('Ajouter un écran','Add a screen')}</button><button class="button" data-action="media-new">${I.upload} ${t('Ajouter un média','Add media')}</button>`)
 +`<div class="howto"><span class="n">1</span><span>${t('Sur le téléviseur, ouvrez','On the TV, open')} <strong class="mono-link">${h(player.replace(/^https?:\/\//,''))}</strong></span><span class="n">2</span><span>${t('Saisissez le code à 6 chiffres de l’écran.','Enter the screen’s 6-digit code.')}</span><span class="n">3</span><span>${t('Le contenu se met à jour seul chaque minute et reste affiché hors connexion.','Content refreshes every minute and keeps playing offline.')}</span></div>`
 +`<section class="panel"><div class="panel-head"><h2>${t('Téléviseurs','Displays')}</h2><span class="badge">${screens.length}</span></div>${screens.length?`<div class="grid pad">${screens.map(s=>`<article class="card screen-card"><div class="row" style="margin:0;justify-content:space-between"><h3>${I.tv} ${h(s.name)}</h3>${+s.paired?`<span class="badge ${online(s)?'good':'bad'}">${online(s)?t('En ligne','Online'):t('Hors ligne','Offline')}</span>`:`<span class="badge warn">${t('À appairer','Not paired')}</span>`}</div>${+s.paired?`<p>${s.last_seen?t('Vu ','Seen ')+ago(s.last_seen):t('Jamais connecté','Never connected')}</p>`:s.pin&&s.pin_expires_at>now()?`<div class="pin" aria-label="${t('Code','Code')}">${h(s.pin.slice(0,3))} ${h(s.pin.slice(3))}</div><p>${t('Code valable jusqu’à','Code valid until')} ${clock(s.pin_expires_at)}</p>`:`<p>${t('Code expiré : générez-en un nouveau.','Code expired: generate a new one.')}</p>`}<div class="row"><button class="button secondary small" data-screen-edit="${s.id}">${I.edit}</button><button class="button secondary small" data-screen-pin="${s.id}">${+s.paired?t('Réappairer','Re-pair'):t('Nouveau code','New code')}</button><button class="button secondary small" data-screen-del="${s.id}" aria-label="${t('Supprimer','Delete')}">${I.trash}</button></div></article>`).join('')}</div>`:`<p class="empty"><strong>${t('Aucun écran','No screens yet')}</strong>${t('Ajoutez un écran pour obtenir son code d’appairage.','Add a screen to get its pairing code.')}</p>`}</section>`
 +`<section class="panel"><div class="panel-head"><h2>${t('Médias','Media')}</h2><span class="badge">${media.length} · ${(used/1048576).toFixed(0)} ${t('Mo','MB')} / 1024</span></div>${media.length?`<div class="media-grid">${media.map(c=>`<article class="mcard ${+c.active?'':'off'}"><div class="mthumb">${c.kind==='video'?`<video src="${h(c.path)}#t=1" muted playsinline preload="metadata"></video><span class="mkind">▶ ${t('Vidéo','Video')}</span>`:`<img src="${h(c.path)}" alt="" loading="lazy">`}</div><div class="mbody"><strong>${h(c.title||t('Sans titre','Untitled'))}</strong><small>${c.kind==='image'?c.duration+' s · ':''}${h(sched(c))}</small><small>${h(tg(c))}</small><div class="row"><button class="toggle" role="switch" aria-checked="${!!+c.active}" data-media-toggle="${c.id}"><i></i>${+c.active?t('Affiché','Showing'):t('Masqué','Hidden')}</button><button class="button secondary small" data-media-edit="${c.id}">${I.edit}</button><button class="button secondary small" data-media-del="${c.id}" aria-label="${t('Supprimer','Delete')}">${I.trash}</button></div></div></article>`).join('')}</div>`:`<p class="empty"><strong>${t('Aucun média','No media yet')}</strong>${t('Images JPEG/PNG/WebP ou vidéos MP4/WebM (50 Mo max).','JPEG/PNG/WebP images or MP4/WebM videos (50 MB max).')}</p>`}</section>`;
}
function screenForm(s={}){dialog(s.id?h(s.name):t('Nouvel écran','New screen'),form('screen-save',restaurantField(s.restaurant_id||workRid())+field('name',t('Nom de l’écran','Screen name'),s.name||'','text',true,`maxlength="80" placeholder="${t('Entrée, bar, terrasse…','Entrance, bar, terrace…')}"`,'full'),s.id||''))}
function mediaUploadForm(){const rid=workRid(),screens=(state.screens||[]).filter(s=>s.restaurant_id==rid);dialog(t('Ajouter un média','Add media'),`<form data-media-upload="${rid}"><div class="field"><label for="m-file">${t('Image (JPEG, PNG, WebP · 15 Mo) ou vidéo (MP4, WebM · 50 Mo). Format paysage 16:9 conseillé.','Image (JPEG, PNG, WebP · 15 MB) or video (MP4, WebM · 50 MB). Landscape 16:9 recommended.')}</label><input id="m-file" name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" required></div><div class="form-grid">${field('title',t('Titre','Title'),'','text',false,'maxlength="120"')}${select('screen_id',t('Diffuser sur','Show on'),[['',t('Tous les écrans','All screens')],...screens.map(s=>[s.id,s.name])],'')}</div><div class="progress" hidden><i></i></div><p class="form-error" role="alert"></p><button class="button" type="submit">${I.upload} ${t('Téléverser','Upload')}</button></form>`)}
function mediaForm(c){const screens=(state.screens||[]).filter(s=>s.restaurant_id==c.restaurant_id),ids=(state.signage_targets||[]).filter(x=>x.content_id==c.id).map(x=>x.screen_id);
 dialog(h(c.title||t('Média','Media')),`${c.kind==='video'?`<video src="${h(c.path)}" controls muted playsinline class="preview"></video>`:`<img src="${h(c.path)}" alt="" class="preview">`}`+form('signage-save',field('title',t('Titre','Title'),c.title||'','text',false,'maxlength="120"','full')+(c.kind==='image'?field('duration',t('Durée d’affichage (s)','Display time (s)'),c.duration,'number',true,'min="3" max="600"'):`<input type="hidden" name="duration" value="${c.duration}">`)+field('sort_order',t('Ordre','Order'),c.sort_order||0,'number')+field('start_date',t('À partir du','From'),c.start_date||'','date',false)+field('end_date',t('Jusqu’au','Until'),c.end_date||'','date',false)+`<div class="field full"><span class="label">${t('Écrans (aucun coché = tous)','Screens (none ticked = all)')}</span><div class="allergen-picks">${screens.map(s=>`<label><input type="checkbox" name="screen" value="${s.id}" ${ids.includes(s.id)?'checked':''}> ${h(s.name)}</label>`).join('')||`<span class="muted">${t('Aucun écran pour l’instant.','No screens yet.')}</span>`}</div></div><div class="field"><span class="label">&nbsp;</span><label class="checkline"><input type="checkbox" name="active" ${+c.active?'checked':''}> ${t('Affiché','Showing')}</label></div>`,c.id))}

