function teamPage(){return heading(t('Équipe & accès','Team & access'),(state.mfa_required?t('Invitations nominatives, double vérification obligatoire, suspension immédiate.','Named invitations, mandatory two-step verification, instant suspension.'):t('Invitations nominatives et suspension immédiate.','Named invitations and instant suspension.')),`<button class="button" data-action="invite">${I.plus} ${t('Inviter','Invite')}</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Nom','Name')}</th><th>E-mail</th><th>${t('Rôle','Role')}</th><th>${t('État','Status')}</th><th></th></tr></thead><tbody>${(state.users||[]).filter(u=>u.role!=='platform_admin'||me.role==='platform_admin').map(u=>`<tr><td><strong>${h(u.name)}</strong>${me.role==='platform_admin'&&u.restaurant_id?`<small>${h(restaurantOf(u.restaurant_id)?.name||'')}</small>`:''}</td><td>${h(u.email)}</td><td>${h(label(u.role))}</td><td>${!+u.active?`<span class="badge bad">${t('Suspendu','Suspended')}</span>`:+u.mfa_enabled?`<span class="badge good">${t('Actif · 2FA','Active · 2FA')}</span>`:+u.activated&&!state.mfa_required?`<span class="badge good">${t('Actif','Active')}</span>`:+u.activated?`<span class="badge warn">${t('2FA à configurer','2FA pending')}</span>`:`<span class="badge info">${t('Invité','Invited')}</span>`}</td><td style="text-align:end">${u.role==='platform_admin'||u.id==me.id?'':`<button class="button secondary small" data-user="${u.id}">${+u.active?t('Suspendre','Suspend'):t('Réactiver','Reactivate')}</button>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function restaurantsPage(){return heading('Restaurants',t('Abonnements, adresses de menu et prise de commandes.','Subscriptions, menu addresses and ordering.'),`<button class="button" data-action="new-restaurant">${I.plus} ${t('Nouveau restaurant','New restaurant')}</button>`)+`<div class="grid">${state.restaurants.map(r=>{const expired=r.subscription_end<new Date().toISOString().slice(0,10);return`<article class="card"><div class="row" style="margin:0"><span class="badge ${['active','trial'].includes(r.subscription_status)&&!expired?'good':'bad'}">${h(label(r.subscription_status))}${expired?' · '+t('expiré','expired'):''}</span><span class="badge ${+r.accepting_orders?'good':''}">${+r.accepting_orders?t('Ouvert','Open'):t('Fermé','Closed')}</span></div><h3>${h(r.name)}</h3><p><a href="/r/${h(r.slug)}" target="_blank" rel="noopener" style="color:var(--brand)">/r/${h(r.slug)}</a> · ${h(r.subscription_plan)}<br>${t('Échéance','Ends')} ${date(r.subscription_end)} · ${h(r.currency)}</p><div class="row"><button class="button secondary small" data-restaurant="${r.id}">${t('Configurer','Configure')}</button><button class="button secondary small" data-toggle-orders="${r.id}">${+r.accepting_orders?t('Fermer les commandes','Close ordering'):t('Ouvrir les commandes','Open ordering')}</button></div></article>`}).join('')||`<p class="empty">${t('Aucun restaurant.','No restaurants yet.')}</p>`}</div>`}
function auditPage(){return heading(t('Journal d’activité','Activity log'),t('Actions sensibles, sans contenu client ni secret.','Sensitive actions, without customer content or secrets.'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Date','Date')}</th><th>${t('Événement','Event')}</th><th>${t('Élément','Entity')}</th><th>${t('Utilisateur','User')}</th></tr></thead><tbody>${(state.audit||[]).map(a=>`<tr><td class="num">${date(a.created_at)}</td><td><span class="badge ${/failed/.test(a.event)?'bad':'info'}">${h(a.event)}</span></td><td>${h(a.entity)} ${a.entity_id?'#'+h(a.entity_id):''}</td><td>${h((state.users||[]).find(u=>u.id==a.user_id)?.name||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}
function securityPage(){return heading(t('Sécurité du compte','Account security'),t('Changez votre phrase de passe ou remplacez vos codes de secours.','Change your passphrase or replace your recovery codes.'))+`<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(320px,1fr))"><section class="panel"><div class="panel-head"><h2>${t('Phrase de passe','Passphrase')}</h2></div><div class="panel-body">${secureForm('security-change',field('current_password',t('Phrase actuelle','Current passphrase'),'','password',true,'autocomplete="current-password"','full')+field('new_password',t('Nouvelle phrase (15 caractères min.)','New passphrase (15+ characters)'),'','password',true,'autocomplete="new-password" minlength="15"','full')+field('confirm',t('Confirmer','Confirm'),'','password',true,'autocomplete="new-password"','full'),t('Mettre à jour','Update'))}</div></section><section class="panel"><div class="panel-head"><h2>${t('Codes de secours','Recovery codes')}</h2></div><div class="panel-body" style="display:grid;gap:14px"><p style="color:var(--muted)">${t('Générer de nouveaux codes invalide immédiatement les anciens.','Generating new codes immediately invalidates the old ones.')}</p>${secureForm('recovery-regenerate',field('password',t('Phrase de passe','Passphrase'),'','password',true,'autocomplete="current-password"','full'),t('Générer de nouveaux codes','Generate new codes'))}</div></section></div>`}

