/* ---------- Data & alerts ---------- */
function chime(){if(!sound)return;try{actx=actx||new(window.AudioContext||window.webkitAudioContext)();if(actx.state==='suspended')actx.resume();const n0=actx.currentTime;[784,1175,1568].forEach((f,i)=>{const o=actx.createOscillator(),g=actx.createGain(),s=n0+i*.16;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,s);g.gain.exponentialRampToValueAtTime(.28,s+.02);g.gain.exponentialRampToValueAtTime(.0001,s+.55);o.connect(g).connect(actx.destination);o.start(s);o.stop(s+.6)})}catch{}}
function detect(){
 const newIds=state.orders.filter(o=>o.status==='new').map(o=>o.id),callIds=state.calls.map(c=>c.id);
 if(seenOrders===null){seenOrders=new Set(state.orders.map(o=>o.id));seenCalls=new Set(callIds);return}
 const incoming=state.orders.filter(o=>!seenOrders.has(o.id)),calls=state.calls.filter(c=>!seenCalls.has(c.id));
 incoming.forEach(o=>{seenOrders.add(o.id);fresh.add(o.id)});calls.forEach(c=>seenCalls.add(c.id));
 // Orders this device just keyed in itself are highlighted but do not ring.
 const others=incoming.filter(o=>o.created_by!=me.id);
 if(others.length||calls.length){if($('#saver'))saverHide();chime();if(navigator.vibrate)navigator.vibrate(200);toast(others.length?(others.length>1?others.length+' '+t('nouvelles commandes','new orders'):t('Nouvelle commande · ','New order · ')+where(others[0])):t('Table ','Table ')+calls[0].table_label+' · '+label(calls[0].kind))}
 setTimeout(()=>{incoming.forEach(o=>fresh.delete(o.id))},12000);
 void newIds;
}
async function load(background=false){
 const s=await api('dashboard');state=s;me=s.user;offset=s.now-Date.now()/1000;detect();
 const typing=document.activeElement&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);
 if(!background||(view==='orders'&&!modal.open)||(view==='analytics'&&!modal.open)||(view==='waiter'&&take&&!take.picked&&!modal.open))render();
 else if(!typing){const c=$('#live-count');if(c)c.textContent=liveCount();document.title=(liveCount()?`(${liveCount()}) `:'')+'APS Order · '+t('Équipe','Team')}
 schedule();
}
function schedule(){clearTimeout(pollTimer);if(me)pollTimer=setTimeout(async()=>{if(!me)return;if(document.hidden){schedule();return}try{await load(true)}catch(e){if(e.message!=='auth')schedule()}},10000)}
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&me){try{await load(true)}catch{}if(view==='orders')requestWake()}});
async function requestWake(){try{if('wakeLock'in navigator&&!wakeLock){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>wakeLock=null)}}catch{}}

/* ---------- Events ---------- */
document.addEventListener('click',async e=>{
 const x=e.target.closest('[data-action],[data-auth],[data-view],[data-order],[data-category],[data-item],[data-table],[data-qr],[data-restaurant],[data-availability],[data-user],[data-toggle-orders],[data-advance],[data-resolve],[data-paid],[data-set-status],[data-set-pay],[data-menu-cat],[data-photo],[data-copy],[data-take-add],[data-take-dec],[data-take-cat],[data-take-line],[data-take-type],[data-take-pay],[data-take-start],[data-screen-edit],[data-screen-pin],[data-screen-del],[data-media-edit],[data-media-del],[data-media-toggle]');if(!x)return;
 const a=x.dataset.action;
 try{
  if(x.dataset.auth)return renderAuth(x.dataset.auth);
  if(x.dataset.view){view=x.dataset.view;store.set('aps-order-staff-view',view);$('#side')?.classList.remove('open');render();window.scrollTo(0,0);return}
  if(x.dataset.takeAdd){const id=+x.dataset.takeAdd,l=take.lines.find(q=>q.item_id===id&&!q.note);if(l)l.quantity=Math.min(20,l.quantity+1);else take.lines.push({item_id:id,quantity:1,note:''});return paintTake()}
  if(x.dataset.takeDec){for(let n=take.lines.length-1;n>=0;n--)if(take.lines[n].item_id==x.dataset.takeDec){if(--take.lines[n].quantity<1)take.lines.splice(n,1);break}return paintTake()}
  if(x.dataset.takeLine){const l=take.lines[+x.dataset.takeLine];if(l){l.quantity=Math.min(20,l.quantity+ +x.dataset.d);if(l.quantity<1)take.lines.splice(+x.dataset.takeLine,1)}return paintTake()}
  if(x.dataset.takeCat){take.cat=x.dataset.takeCat;document.querySelectorAll('[data-take-cat]').forEach(b=>b.setAttribute('aria-pressed',String(b===x)));return paintTake()}
  if(x.dataset.takeType){take.type=x.dataset.takeType;return paintTake()}
  if(x.dataset.takePay){take.pay=x.dataset.takePay;return paintTake()}
  if(x.dataset.takeStart){take.type=x.dataset.takeStart;take.table=x.dataset.id?+x.dataset.id:null;take.picked=true;const tb=state.tables.find(q=>q.id==take.table);if(tb&&take.guests<2)take.guests=Math.min(tb.seats,2);saveTake();render();window.scrollTo(0,0);return}
  if(a==='take-back'){take.picked=false;saveTake();render();window.scrollTo(0,0);return}
  if(a==='take-review'){if(view==='reception')return $('#take-ticket')?.scrollIntoView({behavior:'smooth',block:'start'});return dialog(h(takeWhere()),`<div class="take-ticket" id="take-ticket">${takeTicketBody()}</div>`)}
  if(a==='take-send')return takeSend(x);
  if(a==='take-clear'){if(!confirm(t('Vider la commande en cours ?','Clear the current order?')))return;take.lines=[];take.note='';take.name='';take.allergies=[];take.paid=false;return paintTake()}
  if(a==='close-modal')return modal.close();
  if(a==='print-order'){detail=await api('order-detail',{id:+x.dataset.id});return printTicket()}
  if(a==='kiosk'){try{await document.documentElement.requestFullscreen?.()}catch{}requestWake();return}
  if(a==='saver-settings')return dialog(t('Veille de l’écran','Screen saver'),`<p class="muted">${t('Sans activité, l’écran de réception n’affiche plus que votre logo sur fond noir. Un simple toucher le réactive ; une nouvelle commande aussi.','When idle, the reception screen shows only your logo on black. A touch wakes it, and so does a new order.')}</p><div class="seg">${[0,1,2,5,10].map(m=>`<button data-action="saver-set" data-min="${m}" aria-pressed="${m?saver.on&&saver.min===m:!saver.on}">${m?m+' min':t('Désactivée','Off')}</button>`).join('')}</div><button class="button secondary" data-action="saver-test">${I.moon} ${t('Essayer maintenant','Try it now')}</button>`);
  if(a==='saver-set'){const m=+x.dataset.min;saver=m?{on:true,min:m}:{on:false,min:saver.min||2};store.set('aps-order-saver',saver);modal.close();render();return}
  if(a==='saver-test'){modal.close();return saverShow()}
  if(a==='screen-new')return screenForm();
  if(x.dataset.screenEdit)return screenForm(state.screens.find(s=>s.id==x.dataset.screenEdit));
  if(x.dataset.screenPin){const s=state.screens.find(q=>q.id==x.dataset.screenPin);if(+s?.paired&&!confirm(t('Le téléviseur sera déconnecté et devra saisir le nouveau code. Continuer ?','The TV will be disconnected and must enter the new code. Continue?')))return;await api('screen-pin',{id:+x.dataset.screenPin});await load();return}
  if(x.dataset.screenDel){if(!confirm(t('Supprimer cet écran ?','Delete this screen?')))return;await api('screen-delete',{id:+x.dataset.screenDel});await load();toast(t('Écran supprimé.','Screen deleted.'));return}
  if(a==='media-new')return mediaUploadForm();
  if(x.dataset.mediaEdit)return mediaForm(state.signage.find(c=>c.id==x.dataset.mediaEdit));
  if(x.dataset.mediaDel){if(!confirm(t('Supprimer ce média de tous les écrans ?','Delete this media from every screen?')))return;await api('signage-delete',{id:+x.dataset.mediaDel});await load();toast(t('Média supprimé.','Media deleted.'));return}
  if(x.dataset.mediaToggle){const c=state.signage.find(q=>q.id==x.dataset.mediaToggle),ids=state.signage_targets.filter(q=>q.content_id==c.id&&q.screen_id).map(q=>q.screen_id);await api('signage-save',{id:c.id,title:c.title,duration:c.duration,sort_order:c.sort_order,start_date:c.start_date||'',end_date:c.end_date||'',active:!+c.active,screens:ids});await load();return}
  if(a==='logout'){await api('logout',{});me=null;state=null;clearTimeout(pollTimer);seenOrders=null;renderAuth();return}
  if(a==='menu-toggle')return $('#side').classList.toggle('open');
  if(a==='sound'){sound=!sound;store.set('aps-order-sound',sound);if(sound){chime();requestWake()}render();toast(sound?t('Alerte sonore activée pour les commandes et les appels.','Sound alerts on for orders and calls.'):t('Alerte sonore coupée.','Sound alerts off.'));return}
  if(a==='kitchen'){try{await document.documentElement.requestFullscreen?.()}catch{}requestWake();if(!sound){sound=true;store.set('aps-order-sound',true);chime();render()}return}
  if(a==='recovery-done'){recovery=null;await load();return}
  if(a==='print-ticket')return printTicket();
  if(a==='print-all')return printCards(state.tables.filter(t=>+t.active));
  if(a==='print-one')return printCards(state.tables.filter(q=>q.id==x.dataset.id));
  if(x.dataset.copy!==undefined){try{await navigator.clipboard.writeText(x.dataset.copy);toast(t('Copié.','Copied.'))}catch{toast(t('Copie impossible : sélectionnez le texte.','Copy failed: select the text instead.'),true)}return}
  if(a==='new-restaurant')return restaurantForm();
  if(x.dataset.restaurant)return restaurantForm(state.restaurants.find(r=>r.id==x.dataset.restaurant));
  if(a==='new-category')return categoryForm();
  if(x.dataset.category)return categoryForm(state.categories.find(r=>r.id==x.dataset.category));
  if(a==='new-item')return itemForm();
  if(x.dataset.item)return itemForm(state.items.find(r=>r.id==x.dataset.item));
  if(a==='new-table')return tableForm();
  if(x.dataset.table)return tableForm(state.tables.find(r=>r.id==x.dataset.table));
  if(x.dataset.menuCat){menuCat=x.dataset.menuCat;return render()}
  if(x.dataset.order)return await orderDetail(+x.dataset.order);
  if(x.dataset.advance){x.disabled=true;await api('order-update',{id:+x.dataset.advance,status:x.dataset.to});await load();return}
  if(x.dataset.paid){x.disabled=true;await api('order-update',{id:+x.dataset.paid,payment_status:'paid'});await load();toast(t('Commande encaissée.','Order marked paid.'));return}
  if(x.dataset.setStatus){await api('order-update',{id:+x.dataset.id,status:x.dataset.setStatus});await orderDetail(+x.dataset.id);await load(true);return}
  if(x.dataset.setPay){await api('order-update',{id:+x.dataset.id,payment_status:x.dataset.setPay});await orderDetail(+x.dataset.id);await load(true);return}
  if(x.dataset.resolve){x.disabled=true;await api('call-resolve',{id:+x.dataset.resolve});await load();return}
  if(x.dataset.availability){const it=state.items.find(i=>i.id==x.dataset.availability);await api('item-availability',{id:+x.dataset.availability});if(it)it.available=+it.available?0:1;render();toast(+it?.available?t('Article disponible.','Item available.'):t('Article marqué épuisé.','Item marked sold out.'));return}
  if(x.dataset.user){await api('user-toggle',{id:+x.dataset.user});await load();return}
  if(x.dataset.toggleOrders){await api('restaurant-toggle-orders',{id:+x.dataset.toggleOrders});await load();toast(t('Prise de commandes mise à jour.','Ordering updated.'));return}
  if(a==='invite')return dialog(t('Inviter une personne','Invite someone'),form('invite',restaurantField('')+field('name',t('Nom','Name'),'','text',true,'','full')+field('email','E-mail','','email',true,'','full')+(me.role==='platform_admin'?select('role',t('Rôle','Role'),[['restaurant_admin',t('Responsable','Manager')],['staff',t('Équipe','Staff')]],'restaurant_admin','full'):''),'',t('Envoyer l’invitation','Send invitation')));
  if(x.dataset.qr){const r=state.tables.find(q=>q.id==x.dataset.qr),url=tableUrl(r);return dialog(t('Table ','Table ')+h(r.label),`<div class="qr">${qrSvg(url)}</div><div class="link-box">${h(url)}</div><div class="row" style="display:flex;gap:8px;flex-wrap:wrap"><button class="button" data-action="print-one" data-id="${r.id}">${I.print} ${t('Imprimer','Print')}</button><button class="button secondary" data-copy="${h(url)}">${I.copy} ${t('Copier le lien','Copy link')}</button><a class="button secondary" href="${h(url)}" target="_blank" rel="noopener">${t('Ouvrir le menu','Open menu')}</a></div>`)}
  if(x.dataset.photo){const item=state.items.find(i=>i.id==x.dataset.photo);return dialog(t('Photo','Photo')+' · '+h(item?.name_fr||''),`${item?.image_path?`<img src="${h(item.image_path)}" alt="" style="border-radius:12px;max-height:240px;object-fit:cover;width:100%">`:''}<form data-upload="${h(x.dataset.photo)}"><div class="field"><label for="upload-photo">${t('JPEG, PNG ou WebP · 200 px minimum · 3 Mo maximum. L’image est recadrée et optimisée automatiquement.','JPEG, PNG or WebP · at least 200 px · 3 MB max. The image is optimised automatically.')}</label><input id="upload-photo" name="image" type="file" accept="image/jpeg,image/png,image/webp" required></div><button class="button" type="submit">${t('Téléverser','Upload')}</button></form>`)}
 }catch(err){toast(message(err.message),true);x.disabled=false}
});
$('#modal-close').addEventListener('click',()=>modal.close());
modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
modal.addEventListener('close',()=>{detail=null;if(view==='orders'&&state)render();if(view==='waiter'&&state&&take)paintTake()});
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='take-search'){take.q=el.value;const g=$('#take-grid');if(g)g.innerHTML=takeGrid();return}
 if(el.dataset.takeNote!==undefined){const l=take.lines[+el.dataset.takeNote];if(l){l.note=el.value;saveTake()}return}
 if(el.dataset.takeField){take[el.dataset.takeField]=el.dataset.takeField==='guests'?Math.max(1,Math.min(30,+el.value||1)):el.value;saveTake();return}
 if(e.target.id==='menu-search'){menuQuery=e.target.value;const pos=e.target.selectionStart;render();const s=$('#menu-search');s.focus();s.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.matches('[data-lang-select]')){lang=el.value;store.set('aps-order-staff-lang',lang);return me&&state?render():renderAuth()}
 if(el.matches('[data-admin-rid]')){adminRid=+el.value;take=null;return render()}
 if(el.matches('[data-take-table]')){take.table=el.value?+el.value:null;return paintTake()}
 if(el.dataset.takeAllergy){take.allergies=el.checked?[...new Set([...take.allergies,el.dataset.takeAllergy])]:take.allergies.filter(a=>a!==el.dataset.takeAllergy);saveTake();const s=el.closest('details')?.querySelector('summary');if(s)s.textContent='⚠ '+t('Allergies','Allergies')+(take.allergies.length?' · '+take.allergies.length:'');return}
 if(el.matches('[data-take-paid]')){take.paid=el.checked;return saveTake()}
 if(e.target.name!=='restaurant_id'||e.target.form?.dataset.form!=='item-save')return;const category=e.target.form.elements.category_id,choices=state.categories.filter(c=>c.restaurant_id==e.target.value);category.innerHTML=choices.map(c=>`<option value="${c.id}">${h(c.name_fr)}</option>`).join('')});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!f.dataset.security&&!f.dataset.upload&&!f.dataset.form&&!f.dataset.logo&&!f.dataset.mediaUpload)return;e.preventDefault();
 const b=e.submitter||f.querySelector('[type=submit]');if(b)b.disabled=true;const err=f.querySelector('.form-error');if(err)err.textContent='';
 try{
  if(f.dataset.security){const d=Object.fromEntries(new FormData(f));if(f.dataset.security==='security-change'&&d.new_password!==d.confirm)throw new Error('validation');const r=await api(f.dataset.security,d);if(r.recovery_codes){recovery=r.recovery_codes;renderAuth('recovery');return}toast(t('Phrase de passe changée. Reconnectez-vous.','Passphrase changed. Sign in again.'));me=null;state=null;clearTimeout(pollTimer);renderAuth();return}
  if(f.dataset.logo){const d=new FormData(f);d.set('kind','logo');d.set('restaurant_id',f.dataset.logo);d.set('csrf',csrf);let r,x;try{r=await fetch('/upload.php',{method:'POST',credentials:'same-origin',body:d});x=await r.json()}catch{throw new Error('unavailable')}if(!r.ok||!x.ok)throw new Error(x.error||'unavailable');await load();toast(t('Logo enregistré.','Logo saved.'));return}
  if(f.dataset.mediaUpload){
   // XHR rather than fetch so a 50 MB video shows upload progress.
   const d=new FormData(f);d.set('kind','signage');d.set('restaurant_id',f.dataset.mediaUpload);d.set('csrf',csrf);const bar=f.querySelector('.progress');bar.hidden=false;
   const x=await new Promise((ok,ko)=>{const q=new XMLHttpRequest();q.open('POST','/upload.php');q.withCredentials=true;q.upload.onprogress=ev=>{if(ev.lengthComputable)bar.firstElementChild.style.width=(ev.loaded/ev.total*100).toFixed(1)+'%'};q.onload=()=>{let j=null;try{j=JSON.parse(q.responseText)}catch{}if(q.status===413&&!j)return ko(new Error('too_large'));if(!j)return ko(new Error('unavailable'));j.ok&&q.status<300?ok(j):ko(new Error(j.error||'unavailable'))};q.onerror=()=>ko(new Error('offline'));q.send(d)});
   modal.close();await load();toast(t('Média ajouté : il apparaîtra sur les écrans d’ici une minute.','Media added: it will show on the screens within a minute.'));const c=state.signage.find(q=>q.id==x.id);if(c)mediaForm(c);return}
  if(f.dataset.upload){const d=new FormData(f);d.set('item_id',f.dataset.upload);d.set('csrf',csrf);let r,x;try{r=await fetch('/upload.php',{method:'POST',credentials:'same-origin',body:d});x=await r.json()}catch{throw new Error('unavailable')}if(!r.ok||!x.ok)throw new Error(x.error||'unavailable');modal.close();await load();toast(t('Photo enregistrée.','Photo saved.'));return}
  const d=Object.fromEntries(new FormData(f));if(f.dataset.id)d.id=+f.dataset.id;
  if(d.price_mad!==undefined){const v=parseFloat(String(d.price_mad).replace(',','.'));if(!isFinite(v)||v<0)throw new Error('validation');d.price=Math.round(v*100);delete d.price_mad}
  for(const k of['tax','service'])if(d[k+'_pct']!==undefined){const v=parseFloat(String(d[k+'_pct']).replace(',','.'));if(!isFinite(v)||v<0||v>100)throw new Error('validation');d[k+'_rate']=Math.round(v*100);delete d[k+'_pct']}
  for(const k of['restaurant_id','category_id','sort_order','seats','duration'])if(d[k]!==undefined&&d[k]!=='')d[k]=+d[k];
  if(f.dataset.form==='restaurant-settings'){d.languages=new FormData(f).getAll('lang');delete d.lang}
  if(f.dataset.form==='signage-save'){d.screens=new FormData(f).getAll('screen').map(Number);delete d.screen}
  for(const k of['active','available','featured'])if(f.elements[k])d[k]=!!f.elements[k].checked;
  if(f.dataset.form==='item-save')d.allergens=new FormData(f).getAll('allergen');delete d.allergen;
  if(f.dataset.form==='activate'){if(d.password!==d.confirm)throw new Error('validation');d.token=activation}
  const r=await api(f.dataset.form,d);
  if(f.dataset.form==='login'){if(r.next==='done'){me=r.user;seenOrders=null;await load();return}if(r.next==='enroll'){enroll=await api('enroll');renderAuth('enroll')}else renderAuth('verify');return}
  if(f.dataset.form==='verify'){me=r.user;seenOrders=null;await load();return}
  if(f.dataset.form==='confirm-enroll'){me=r.user;recovery=r.recovery_codes;renderAuth('recovery');return}
  if(f.dataset.form==='request-link'){toast(t('Si ce compte existe, un lien vient d’être envoyé.','If this account exists, a link has been sent.'));renderAuth('login');return}
  if(f.dataset.form==='activate'){activation='';renderAuth('login');toast(t('Phrase de passe enregistrée. Connectez-vous.','Passphrase saved. Sign in now.'));return}
  if(f.dataset.form==='invite'&&r.mail_sent===false)toast(t('Compte créé, mais l’e-mail n’a pas pu partir. Utilisez « Mot de passe oublié ».','Account created, but the email could not be sent. Use “Forgot password”.'),true);
  modal.close();await load();if(!(f.dataset.form==='invite'&&r.mail_sent===false))toast(t('Enregistré.','Saved.'));
 }catch(x){const m=message(x.message);if(err)err.textContent=m;toast(m,true)}finally{if(b)b.disabled=false}
});

/* ---------- Boot ---------- */
(async()=>{
 view=store.get('aps-order-staff-view','orders');
 if(location.hash.startsWith('#activate=')){activation=location.hash.slice(10);history.replaceState(null,'',location.pathname)}
 try{const s=await api('session');me=s.user;if(me&&!activation)await load();else renderAuth()}catch(e){renderAuth();toast(message(e.message),true)}
})();
